-- Phase 4B: controlled existing-client migration and reconciliation.
alter table app_private.outbox_events drop constraint outbox_events_producer_module_check;
alter table app_private.outbox_events add constraint outbox_events_producer_module_check check (producer_module in ('identity-access','clients','service-addresses','service-configuration','geography','workforce','vehicles','daily-roster','routes','route-operations','vehicle-tracking','operational-issues','needs-attention','communications','integrations','configuration','reporting','audit','system-health','platform-runtime','operational-intelligence','website-intake','client-migration'));

insert into app_private.permissions(permission_key,description) values
 ('client_migration.read','Read migration batches and sensitive row reconciliation'),('client_migration.create','Create batches and import synthetic or approved source rows'),('client_migration.review','Review and override migration row plans'),('client_migration.approve','Approve and freeze migration batches'),('client_migration.activate','Activate approved migration plans'),('client_migration.retry','Retry technically failed migration rows') on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key)
select r.role_id,p.permission_key from app_private.roles r cross join app_private.permissions p where r.role_key in ('director_admin','operations_manager') and p.permission_key like 'client_migration.%' on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key)
select r.role_id,p.permission_key from app_private.roles r cross join app_private.permissions p where r.role_key='office_admin' and p.permission_key in ('client_migration.read','client_migration.create','client_migration.review') on conflict do nothing;

create table app_private.client_migration_batches(
 client_migration_batch_id uuid primary key default gen_random_uuid(), source_type text not null check(source_type in ('canonical_csv','canonical_json','megabin_spreadsheet')), source_name text not null, source_reference text, source_file_hash text not null check(source_file_hash~'^[a-f0-9]{64}$'), imported_at timestamptz not null default now(), imported_by uuid not null references auth.users, environment_name text not null check(environment_name in ('local','staging','production')), lifecycle_status text not null default 'created' check(lifecycle_status in ('created','uploaded','parsed','validating','needs_review','ready','dry_run_complete','approved','activating','completed','completed_with_exceptions','failed','cancelled','archived')), mapping_version text not null, processing_version text not null default 'phase-4b-v1', row_count integer not null default 0, profile jsonb not null default '{}'::jsonb, dry_run_summary jsonb, reconciliation_report jsonb, approval_snapshot jsonb, approved_by uuid references auth.users, approved_at timestamptz, completed_at timestamptz, notes text, version integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table app_private.client_migration_source_rows(
 client_migration_row_id uuid primary key default gen_random_uuid(), client_migration_batch_id uuid not null references app_private.client_migration_batches on delete restrict, source_row_number integer not null, source_row_key text not null, source_external_client_reference text, source_payload jsonb not null, source_payload_fingerprint text not null check(source_payload_fingerprint~'^[a-f0-9]{64}$'), imported_at timestamptz not null default now(), unique(client_migration_batch_id,source_row_number), unique(client_migration_batch_id,source_row_key));
create table app_private.client_migration_row_versions(
 client_migration_row_version_id uuid primary key default gen_random_uuid(), client_migration_row_id uuid not null references app_private.client_migration_source_rows, processing_version text not null, canonical_data jsonb not null, validation_errors jsonb not null default '[]', reconciliation jsonb not null default '{}'::jsonb, proposed_plan jsonb not null default '{}'::jsonb, classification text not null, service_region_id uuid references app_private.service_regions, created_at timestamptz not null default now(), unique(client_migration_row_id,processing_version));
create table app_private.client_migration_row_decisions(
 client_migration_row_decision_id uuid primary key default gen_random_uuid(), client_migration_row_id uuid not null unique references app_private.client_migration_source_rows, actor_id uuid not null references auth.users, decision text not null check(decision in ('approved','no_change','rejected')), approved_plan jsonb, reason text, version integer not null default 1, decided_at timestamptz not null default now());
create table app_private.client_migration_row_outcomes(
 client_migration_row_outcome_id uuid primary key default gen_random_uuid(), client_migration_row_id uuid not null unique references app_private.client_migration_source_rows, outcome text not null check(outcome in ('activated','failed','skipped','conflict')), attempt_count integer not null default 1, technical_failure_code text, result jsonb, last_attempt_at timestamptz not null default now());
create table app_private.client_migration_entity_provenance(
 client_migration_provenance_id uuid primary key default gen_random_uuid(), client_migration_batch_id uuid not null references app_private.client_migration_batches, client_migration_row_id uuid not null references app_private.client_migration_source_rows, action_identity text not null, entity_type text not null, internal_entity_id uuid not null, action text not null check(action in ('created','linked','configured','referenced')), created_at timestamptz not null default now(), unique(client_migration_row_id,action_identity));
create table app_private.client_migration_team_mappings(source_system text not null, mapping_version text not null, source_team_key text not null, team_id uuid not null references app_private.teams, created_at timestamptz not null default now(), primary key(source_system,mapping_version,source_team_key));
create index client_migration_batches_queue_idx on app_private.client_migration_batches(lifecycle_status,imported_at desc);
create index client_migration_rows_batch_idx on app_private.client_migration_source_rows(client_migration_batch_id,source_row_number);
create index client_migration_versions_region_idx on app_private.client_migration_row_versions(service_region_id,classification);
do $$ declare n text; begin foreach n in array array['client_migration_batches','client_migration_source_rows','client_migration_row_versions','client_migration_row_decisions','client_migration_row_outcomes','client_migration_entity_provenance','client_migration_team_mappings'] loop execute format('alter table app_private.%I enable row level security',n); execute format('revoke all on table app_private.%I from public,anon,authenticated',n); execute format('grant select,insert,update on table app_private.%I to service_role',n); end loop; end $$;

create or replace function app_private.client_migration_require(p_actor uuid,p_permission text,p_region uuid default null,p_global_batch boolean default false) returns void language plpgsql security definer set search_path='' as $$ begin
 if p_global_batch then
  if not app_private.user_has_global_permission(p_actor,p_permission) then raise exception 'global migration permission denied' using errcode='42501'; end if;
 elsif p_region is null then
  if not app_private.user_has_global_permission(p_actor,p_permission) then raise exception 'migration permission denied' using errcode='42501'; end if;
 elsif not app_private.user_has_region_permission(p_actor,p_permission,p_region) then
  raise exception 'regional migration permission denied' using errcode='42501';
 end if;
end $$;

create or replace function api.client_migration_create_batch(p_actor_id uuid,p_body jsonb,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare b app_private.client_migration_batches%rowtype; begin
 perform app_private.client_migration_require(p_actor_id,'client_migration.create',null,true);
 insert into app_private.client_migration_batches(source_type,source_name,source_reference,source_file_hash,imported_by,environment_name,mapping_version,notes) values(p_body->>'sourceType',p_body->>'sourceName',p_body->>'sourceReference',p_body->>'sourceFileHash',p_actor_id,p_body->>'environment',p_body->>'mappingVersion',p_body->>'notes') returning * into b;
 insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state) values('client_migration.batch_created',p_actor_id,'client-migration','migration-batch',b.client_migration_batch_id,p_correlation_id,jsonb_build_object('sourceType',b.source_type,'mappingVersion',b.mapping_version));
 insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at) values('client-migration','ClientMigration.BatchCreated',1,'migration-batch',b.client_migration_batch_id,jsonb_build_object('batchId',b.client_migration_batch_id),p_correlation_id,'user',p_actor_id::text,now()); return to_jsonb(b); end $$;

create or replace function api.client_migration_import_rows(p_actor_id uuid,p_batch_id uuid,p_expected_version integer,p_rows jsonb,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare b app_private.client_migration_batches%rowtype;r jsonb; begin
 select * into b from app_private.client_migration_batches where client_migration_batch_id=p_batch_id for update; if b.version<>p_expected_version or b.lifecycle_status<>'created' then raise exception 'stale_or_frozen_batch' using errcode='40001'; end if; perform app_private.client_migration_require(p_actor_id,'client_migration.create',null,true); if jsonb_array_length(p_rows)>5000 then raise exception 'row_limit_exceeded' using errcode='22023'; end if;
 for r in select value from jsonb_array_elements(p_rows) loop insert into app_private.client_migration_source_rows(client_migration_batch_id,source_row_number,source_row_key,source_external_client_reference,source_payload,source_payload_fingerprint) values(p_batch_id,(r->>'rowNumber')::integer,r->>'rowKey',r->>'externalClientReference',r->'payload',r->>'fingerprint'); end loop;
 update app_private.client_migration_batches set lifecycle_status='uploaded',row_count=jsonb_array_length(p_rows),version=version+1,updated_at=now() where client_migration_batch_id=p_batch_id returning * into b; insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('client_migration.mapping_selected',p_actor_id,'client-migration','migration-batch',p_batch_id,p_correlation_id,jsonb_build_object('mappingVersion',b.mapping_version,'rowCount',b.row_count));return to_jsonb(b); end $$;

create or replace function api.client_migration_process(p_actor_id uuid,p_batch_id uuid,p_expected_version integer,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare b app_private.client_migration_batches%rowtype;s app_private.client_migration_source_rows%rowtype;n jsonb;e jsonb;clients jsonb;addresses jsonb;territories jsonb;region uuid;territory uuid;depot uuid;team uuid;active_duplicate boolean;classification text;begin
 select * into b from app_private.client_migration_batches where client_migration_batch_id=p_batch_id for update; if b.version<>p_expected_version or b.lifecycle_status not in ('uploaded','failed') then raise exception 'stale_or_invalid_batch' using errcode='40001'; end if; perform app_private.client_migration_require(p_actor_id,'client_migration.create',null,true); update app_private.client_migration_batches set lifecycle_status='validating',updated_at=now() where client_migration_batch_id=p_batch_id;
 for s in select * from app_private.client_migration_source_rows where client_migration_batch_id=p_batch_id order by source_row_number loop
  n:=jsonb_strip_nulls(jsonb_build_object('legacyClientReference',s.source_payload->>'legacyClientReference','clientName',btrim(s.source_payload->>'clientName'),'organisationName',nullif(btrim(s.source_payload->>'organisationName'),''),'contactName',btrim(s.source_payload->>'contactName'),'mobileE164',case when regexp_replace(s.source_payload->>'mobile','\D','','g')~'^0[0-9]{9}$' then '+27'||substr(regexp_replace(s.source_payload->>'mobile','\D','','g'),2) when regexp_replace(s.source_payload->>'mobile','\D','','g')~'^27[0-9]{9}$' then '+'||regexp_replace(s.source_payload->>'mobile','\D','','g') end,'email',lower(nullif(btrim(s.source_payload->>'email'),'')),'addressLine1',btrim(s.source_payload->>'addressLine1'),'suburb',btrim(s.source_payload->>'suburb'),'city',btrim(s.source_payload->>'city'),'postalCode',nullif(btrim(s.source_payload->>'postalCode'),''),'latitude',s.source_payload->'latitude','longitude',s.source_payload->'longitude','drumCount',s.source_payload->'drumCount','serviceStartDate',s.source_payload->>'serviceStartDate','collectionDay',s.source_payload->'collectionDay','sourceTeamKey',s.source_payload->>'team','legacyStatus',lower(btrim(s.source_payload->>'legacyStatus')),'agreementReference',s.source_payload->>'agreementReference','billingReference',s.source_payload->>'billingReference'));
  e:='[]'; if coalesce(n->>'legacyClientReference','')='' then e:=e||'["missing_source_reference"]'; end if; if s.source_payload?'mobile' and not(n?'mobileE164') then e:=e||'["invalid_phone"]'; end if; if n?'email' and (n->>'email')!~'^[^@ ]+@[^@ ]+\.[^@ ]+$' then e:=e||'["invalid_email"]'; end if; if coalesce((n->>'drumCount')::integer,0)<=0 then e:=e||'["invalid_drum_count"]'; end if; if coalesce((n->>'collectionDay')::integer,0) not between 1 and 7 then e:=e||'["unsupported_collection_day"]'; end if; if coalesce(n->>'addressLine1','')='' or coalesce(n->>'suburb','')='' or coalesce(n->>'city','')='' then e:=e||'["incomplete_address"]'; end if; if n->>'legacyStatus' not in ('active','pending','cancelled','on hold','on_hold') then e:=e||'["ambiguous_legacy_status"]'; end if;
  select coalesce(jsonb_agg(distinct jsonb_build_object('clientId',c.client_id,'displayName',c.display_name)),'[]') into clients from app_private.clients c left join app_private.client_contacts cc on cc.client_id=c.client_id left join app_private.external_references x on x.internal_entity_id=c.client_id and x.entity_type='client' and x.retired_at is null where (x.external_identifier=n->>'legacyClientReference') or (n?'mobileE164' and cc.mobile_e164=n->>'mobileE164') or (n?'email' and lower(cc.email)=n->>'email');
  select coalesce(jsonb_agg(jsonb_build_object('serviceAddressId',a.service_address_id)),'[]') into addresses from app_private.service_addresses a where a.archived_at is null and lower(a.address_line_1)=lower(n->>'addressLine1') and lower(a.suburb)=lower(n->>'suburb') and lower(a.city)=lower(n->>'city');
  region:=null;territory:=null;depot:=null;territories:='[]'; if n?'latitude' and n?'longitude' then select coalesce(jsonb_agg(to_jsonb(t)),'[]'),(array_agg(t.service_region_id))[1],(array_agg(t.territory_id))[1],(array_agg(t.default_depot_id))[1] into territories,region,territory,depot from app_private.territory_candidates(extensions.st_setsrid(extensions.st_makepoint((n->>'longitude')::float,(n->>'latitude')::float),4326)) t; end if;
  select tm.team_id into team from app_private.client_migration_team_mappings tm where tm.source_system=b.source_type and tm.mapping_version=b.mapping_version and tm.source_team_key=n->>'sourceTeamKey';
  select exists(select 1 from app_private.client_services cs where cs.lifecycle_status='active' and cs.client_id in(select (v->>'clientId')::uuid from jsonb_array_elements(clients)v) and cs.service_address_id in(select (v->>'serviceAddressId')::uuid from jsonb_array_elements(addresses)v)) into active_duplicate;
  classification:=case when jsonb_array_length(e)>0 then 'rejected_invalid' when jsonb_array_length(clients)>1 then 'needs_review_ambiguous_client' when jsonb_array_length(territories)<>1 then 'needs_review_geography_conflict' when nullif(n->>'sourceTeamKey','') is not null and team is null then 'needs_review_team_day_conflict' when active_duplicate then 'ready_existing_service_no_change' when jsonb_array_length(clients)=1 and jsonb_array_length(addresses)=1 then 'ready_existing_client_existing_address_new_service' when jsonb_array_length(clients)=1 then 'ready_existing_client_new_address_service' else 'ready_create_new_client_address_service' end;
  insert into app_private.client_migration_row_versions(client_migration_row_id,processing_version,canonical_data,validation_errors,reconciliation,proposed_plan,classification,service_region_id) values(s.client_migration_row_id,b.processing_version,n,e,jsonb_build_object('clientCandidates',clients,'addressCandidates',addresses,'territories',territories,'activeServiceDuplicate',active_duplicate,'teamId',team,'collectionDayComparison',case when territory is null then 'unresolved' when exists(select 1 from app_private.territories t where t.territory_id=territory and (n->>'collectionDay')::smallint=any(t.preferred_collection_days)) then 'consistent' else 'conflict' end),jsonb_strip_nulls(jsonb_build_object('existingClientId',case when jsonb_array_length(clients)=1 then clients->0->>'clientId' end,'existingServiceAddressId',case when jsonb_array_length(addresses)=1 then addresses->0->>'serviceAddressId' end,'createClient',jsonb_array_length(clients)=0,'createAddress',jsonb_array_length(addresses)=0,'createService',not active_duplicate,'serviceRegionId',region,'territoryId',territory,'depotId',depot,'defaultTeamId',team,'collectionDay',n->'collectionDay','drumCount',n->'drumCount','effectiveStartDate',n->>'serviceStartDate','lifecycleStatus',case when n->>'legacyStatus'='active' then 'active' when n->>'legacyStatus' in ('on hold','on_hold') then 'on_hold' when n->>'legacyStatus'='cancelled' then 'cancelled' else 'pending' end)),classification,region);
 end loop;
 update app_private.client_migration_batches set lifecycle_status='needs_review',profile=(select jsonb_build_object('totalRows',count(*),'invalidRows',count(*)filter(where jsonb_array_length(v.validation_errors)>0),'missingCoordinates',count(*)filter(where not(v.canonical_data?'latitude')),'duplicateSourceReferences',(select count(*) from(select source_external_client_reference from app_private.client_migration_source_rows where client_migration_batch_id=p_batch_id group by source_external_client_reference having count(*)>1)d),'classifications',coalesce(jsonb_object_agg(x.classification,x.n),'{}')) from app_private.client_migration_row_versions v cross join lateral(select classification,count(*) n from app_private.client_migration_row_versions vv join app_private.client_migration_source_rows ss on ss.client_migration_row_id=vv.client_migration_row_id where ss.client_migration_batch_id=p_batch_id group by classification)x where v.client_migration_row_id in(select client_migration_row_id from app_private.client_migration_source_rows where client_migration_batch_id=p_batch_id)),version=version+1,updated_at=now() where client_migration_batch_id=p_batch_id returning * into b;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('client_migration.batch_profiled',p_actor_id,'client-migration','migration-batch',p_batch_id,p_correlation_id,jsonb_build_object('rowCount',b.row_count,'processingVersion',b.processing_version));return to_jsonb(b); end $$;

create or replace function api.client_migration_dry_run(p_actor_id uuid,p_batch_id uuid,p_expected_version integer,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare b app_private.client_migration_batches%rowtype;summary jsonb;begin select * into b from app_private.client_migration_batches where client_migration_batch_id=p_batch_id for update; if b.version<>p_expected_version or b.lifecycle_status not in('needs_review','ready','dry_run_complete') then raise exception 'stale_or_invalid_batch' using errcode='40001';end if;perform app_private.client_migration_require(p_actor_id,'client_migration.review',null,true); select jsonb_build_object('clientsToCreate',count(*)filter(where classification='ready_create_new_client_address_service'),'contactsToCreate',count(*)filter(where classification='ready_create_new_client_address_service'),'addressesToCreate',count(*)filter(where classification in('ready_create_new_client_address_service','ready_existing_client_new_address_service')),'servicesToCreate',count(*)filter(where classification like 'ready_%new%'),'configurationsToCreateOrUpdate',count(*)filter(where classification like 'ready_%new%'),'externalReferencesToCreate',count(*)filter(where classification like 'ready_%')*2,'existingRecordsMatched',count(*)filter(where classification like 'ready_existing%'),'rowsRequiringReview',count(*)filter(where classification like 'needs_review%'),'rowsRejected',count(*)filter(where classification='rejected_invalid'),'rowsUnchanged',count(*)filter(where classification='ready_existing_service_no_change')) into summary from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.client_migration_batch_id=p_batch_id; update app_private.client_migration_batches set lifecycle_status='dry_run_complete',dry_run_summary=summary,version=version+1,updated_at=now() where client_migration_batch_id=p_batch_id;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('client_migration.dry_run_performed',p_actor_id,'client-migration','migration-batch',p_batch_id,p_correlation_id,summary);return summary||jsonb_build_object('batchId',p_batch_id,'authoritativeWrites',0);end $$;

create or replace function api.client_migration_review_row(p_actor_id uuid,p_row_id uuid,p_expected_version integer,p_decision text,p_plan jsonb,p_reason text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v app_private.client_migration_row_versions%rowtype;d app_private.client_migration_row_decisions%rowtype;begin select vv.* into v from app_private.client_migration_row_versions vv where vv.client_migration_row_id=p_row_id order by created_at desc limit 1;perform app_private.client_migration_require(p_actor_id,'client_migration.review',v.service_region_id,v.service_region_id is null);select * into d from app_private.client_migration_row_decisions where client_migration_row_id=p_row_id for update;if d.client_migration_row_decision_id is not null and d.version<>p_expected_version then raise exception 'stale_review' using errcode='40001';end if;if p_plan is distinct from v.proposed_plan and coalesce(length(btrim(p_reason)),0)<3 then raise exception 'override_reason_required' using errcode='22023';end if;insert into app_private.client_migration_row_decisions(client_migration_row_id,actor_id,decision,approved_plan,reason)values(p_row_id,p_actor_id,p_decision,p_plan,p_reason)on conflict(client_migration_row_id)do update set actor_id=excluded.actor_id,decision=excluded.decision,approved_plan=excluded.approved_plan,reason=excluded.reason,version=app_private.client_migration_row_decisions.version+1,decided_at=now() returning * into d;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('client_migration.row_reviewed',p_actor_id,'client-migration','migration-row',p_row_id,p_correlation_id,jsonb_build_object('decision',p_decision,'reason',p_reason));return to_jsonb(d);end $$;

create or replace function api.client_migration_approve(p_actor_id uuid,p_batch_id uuid,p_expected_version integer,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare b app_private.client_migration_batches%rowtype;unresolved integer;begin select * into b from app_private.client_migration_batches where client_migration_batch_id=p_batch_id for update;if b.version<>p_expected_version or b.lifecycle_status<>'dry_run_complete' then raise exception 'stale_or_invalid_batch' using errcode='40001';end if;perform app_private.client_migration_require(p_actor_id,'client_migration.approve',null,true);select count(*) into unresolved from app_private.client_migration_source_rows s left join app_private.client_migration_row_decisions d using(client_migration_row_id) join app_private.client_migration_row_versions v using(client_migration_row_id) where s.client_migration_batch_id=p_batch_id and d.client_migration_row_id is null and v.classification not in('ready_existing_service_no_change','rejected_invalid');if unresolved>0 then raise exception 'unresolved_rows' using errcode='55000';end if;update app_private.client_migration_batches set lifecycle_status='approved',approved_by=p_actor_id,approved_at=now(),approval_snapshot=jsonb_build_object('mappingVersion',mapping_version,'processingVersion',processing_version,'rowCount',row_count,'dryRun',dry_run_summary,'plans',(select coalesce(jsonb_agg(jsonb_build_object('rowId',s.client_migration_row_id,'decision',d.decision,'plan',d.approved_plan)order by s.source_row_number),'[]')from app_private.client_migration_source_rows s left join app_private.client_migration_row_decisions d using(client_migration_row_id)where s.client_migration_batch_id=p_batch_id)),version=version+1,updated_at=now() where client_migration_batch_id=p_batch_id returning * into b;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('client_migration.batch_approved',p_actor_id,'client-migration','migration-batch',p_batch_id,p_correlation_id,jsonb_build_object('rowCount',b.row_count));insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('client-migration','ClientMigration.BatchApproved',1,'migration-batch',p_batch_id,jsonb_build_object('batchId',p_batch_id,'rowCount',b.row_count),p_correlation_id,'user',p_actor_id::text,now());return to_jsonb(b);end$$;

create or replace function api.client_migration_activate_row(p_actor_id uuid,p_row_id uuid,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s app_private.client_migration_source_rows%rowtype;v app_private.client_migration_row_versions%rowtype;d app_private.client_migration_row_decisions%rowtype;b app_private.client_migration_batches%rowtype;o app_private.client_migration_row_outcomes%rowtype;p jsonb;c uuid;a uuid;svc uuid;cfg uuid;r jsonb;begin select * into s from app_private.client_migration_source_rows where client_migration_row_id=p_row_id;select * into b from app_private.client_migration_batches where client_migration_batch_id=s.client_migration_batch_id for update;select * into v from app_private.client_migration_row_versions where client_migration_row_id=p_row_id order by created_at desc limit 1;select * into d from app_private.client_migration_row_decisions where client_migration_row_id=p_row_id;perform app_private.client_migration_require(p_actor_id,'client_migration.activate',v.service_region_id,v.service_region_id is null);select * into o from app_private.client_migration_row_outcomes where client_migration_row_id=p_row_id;if o.outcome='activated' then return o.result||jsonb_build_object('duplicate',true);end if;if b.lifecycle_status not in('approved','activating','completed_with_exceptions') then raise exception 'batch_not_approved' using errcode='55000';end if;if d.decision in('rejected','no_change') or v.classification in('rejected_invalid','ready_existing_service_no_change') then insert into app_private.client_migration_row_outcomes(client_migration_row_id,outcome,result)values(p_row_id,'skipped',jsonb_build_object('rowId',p_row_id))on conflict(client_migration_row_id)do update set outcome='skipped',last_attempt_at=now();return jsonb_build_object('rowId',p_row_id,'outcome','skipped');end if;p:=coalesce(d.approved_plan,v.proposed_plan);c:=nullif(p->>'existingClientId','')::uuid;if c is null then c:=gen_random_uuid();perform api.create_client(p_actor_id,'migration:'||p_row_id||':client',s.source_payload_fingerprint,p_correlation_id,jsonb_build_object('clientId',c,'clientType',case when v.canonical_data?'organisationName'then'organisation'else'individual'end,'displayName',v.canonical_data->>'clientName','organisationName',v.canonical_data->>'organisationName','lifecycleStatus',p->>'lifecycleStatus'));perform api.master_data_create(p_actor_id,'client-contacts',gen_random_uuid(),jsonb_strip_nulls(jsonb_build_object('client_id',c,'contact_name',v.canonical_data->>'contactName','mobile_e164',v.canonical_data->>'mobileE164','email',v.canonical_data->>'email','is_primary',true,'is_active',true)),'migration:'||p_row_id||':contact',s.source_payload_fingerprint,p_correlation_id);end if;a:=nullif(p->>'existingServiceAddressId','')::uuid;if a is null then a:=gen_random_uuid();perform api.create_service_address(p_actor_id,p_correlation_id,jsonb_strip_nulls(jsonb_build_object('serviceAddressId',a,'addressLine1',v.canonical_data->>'addressLine1','suburb',v.canonical_data->>'suburb','city',v.canonical_data->>'city','postalCode',v.canonical_data->>'postalCode','latitude',v.canonical_data->>'latitude','longitude',v.canonical_data->>'longitude')));end if;svc:=gen_random_uuid();perform api.create_client_service(p_actor_id,p_correlation_id,jsonb_build_object('clientServiceId',svc,'clientId',c,'serviceAddressId',a,'lifecycleStatus',p->>'lifecycleStatus','serviceStartDate',p->>'effectiveStartDate','cadenceCode','weekly'));r:=api.configure_service(p_actor_id,p_correlation_id,jsonb_strip_nulls(jsonb_build_object('clientServiceId',svc,'serviceRegionId',p->>'serviceRegionId','territoryId',p->>'territoryId','depotId',p->>'depotId','defaultTeamId',p->>'defaultTeamId','configuredDrumCount',p->>'drumCount','operationalDrumUnitCount',p->>'drumCount','configuredCollectionDay',p->>'collectionDay','effectiveFrom',p->>'effectiveStartDate')));cfg:=(r->>'serviceConfigurationId')::uuid;insert into app_private.external_references(source_system,entity_type,internal_entity_id,external_identifier)values(b.source_type,'client',c,v.canonical_data->>'legacyClientReference'),(b.source_type,'migration-row',p_row_id,s.source_row_key)on conflict do nothing;insert into app_private.client_migration_entity_provenance(client_migration_batch_id,client_migration_row_id,action_identity,entity_type,internal_entity_id,action)values(b.client_migration_batch_id,p_row_id,'client','client',c,case when p?'existingClientId'then'linked'else'created'end),(b.client_migration_batch_id,p_row_id,'address','service-address',a,case when p?'existingServiceAddressId'then'linked'else'created'end),(b.client_migration_batch_id,p_row_id,'service','client-service',svc,'created'),(b.client_migration_batch_id,p_row_id,'configuration','service-configuration',cfg,'configured')on conflict do nothing;r:=jsonb_build_object('rowId',p_row_id,'outcome','activated','clientId',c,'serviceAddressId',a,'clientServiceId',svc,'serviceConfigurationId',cfg,'duplicate',false);insert into app_private.client_migration_row_outcomes(client_migration_row_id,outcome,result)values(p_row_id,'activated',r)on conflict(client_migration_row_id)do update set outcome='activated',attempt_count=app_private.client_migration_row_outcomes.attempt_count+1,result=excluded.result,last_attempt_at=now();insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('client-migration','ClientMigration.RowActivated',1,'migration-row',p_row_id,jsonb_build_object('batchId',b.client_migration_batch_id,'rowId',p_row_id,'clientId',c,'serviceId',svc),p_correlation_id,'user',p_actor_id::text,now());return r;exception when others then insert into app_private.client_migration_row_outcomes(client_migration_row_id,outcome,technical_failure_code,result)values(p_row_id,'failed',sqlstate,jsonb_build_object('rowId',p_row_id))on conflict(client_migration_row_id)do update set outcome='failed',attempt_count=app_private.client_migration_row_outcomes.attempt_count+1,technical_failure_code=sqlstate,last_attempt_at=now();raise;end$$;


create or replace function api.client_migration_retry_row(p_actor_id uuid,p_row_id uuid,p_expected_attempt integer,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare o app_private.client_migration_row_outcomes%rowtype;begin select * into o from app_private.client_migration_row_outcomes where client_migration_row_id=p_row_id for update;if o.outcome<>'failed' then raise exception 'business_outcome_not_retryable' using errcode='55000';end if;if o.attempt_count<>p_expected_attempt then raise exception 'stale_retry' using errcode='40001';end if;return api.client_migration_activate_row(p_actor_id,p_row_id,p_correlation_id);end$$;

create or replace function api.client_migration_list(p_actor_id uuid,p_query jsonb default '{}')returns jsonb language plpgsql security definer set search_path='' as $$begin perform app_private.client_migration_require(p_actor_id,'client_migration.read',null,true);return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('batchId',client_migration_batch_id,'sourceName',source_name,'status',lifecycle_status,'rowCount',row_count,'profile',profile,'dryRunSummary',dry_run_summary,'version',version,'importedAt',imported_at)order by imported_at desc),'[]')from app_private.client_migration_batches where nullif(p_query->>'status','')is null or lifecycle_status=p_query->>'status'));end$$;
create or replace function api.client_migration_detail(p_actor_id uuid,p_batch_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare b app_private.client_migration_batches%rowtype;begin select * into b from app_private.client_migration_batches where client_migration_batch_id=p_batch_id;perform app_private.client_migration_require(p_actor_id,'client_migration.read',null,true);return to_jsonb(b)||jsonb_build_object('batchId',p_batch_id,'rows',(select coalesce(jsonb_agg(jsonb_build_object('rowId',s.client_migration_row_id,'rowNumber',s.source_row_number,'rowKey',s.source_row_key,'source',s.source_payload,'canonical',v.canonical_data,'validationErrors',v.validation_errors,'reconciliation',v.reconciliation,'proposedPlan',v.proposed_plan,'classification',v.classification,'decision',d.decision,'approvedPlan',d.approved_plan,'decisionVersion',coalesce(d.version,0),'outcome',o.outcome,'attemptCount',o.attempt_count)order by s.source_row_number),'[]')from app_private.client_migration_source_rows s left join app_private.client_migration_row_versions v using(client_migration_row_id)left join app_private.client_migration_row_decisions d using(client_migration_row_id)left join app_private.client_migration_row_outcomes o using(client_migration_row_id)where s.client_migration_batch_id=p_batch_id));end$$;

revoke all on function app_private.client_migration_require(uuid,text,uuid,boolean)from public,anon,authenticated;
revoke all on function api.client_migration_create_batch(uuid,jsonb,uuid),api.client_migration_import_rows(uuid,uuid,integer,jsonb,uuid),api.client_migration_process(uuid,uuid,integer,uuid),api.client_migration_dry_run(uuid,uuid,integer,uuid),api.client_migration_review_row(uuid,uuid,integer,text,jsonb,text,uuid),api.client_migration_approve(uuid,uuid,integer,uuid),api.client_migration_activate_row(uuid,uuid,uuid),api.client_migration_retry_row(uuid,uuid,integer,uuid),api.client_migration_list(uuid,jsonb),api.client_migration_detail(uuid,uuid)from public,anon,authenticated;
grant execute on function api.client_migration_create_batch(uuid,jsonb,uuid),api.client_migration_import_rows(uuid,uuid,integer,jsonb,uuid),api.client_migration_process(uuid,uuid,integer,uuid),api.client_migration_dry_run(uuid,uuid,integer,uuid),api.client_migration_review_row(uuid,uuid,integer,text,jsonb,text,uuid),api.client_migration_approve(uuid,uuid,integer,uuid),api.client_migration_activate_row(uuid,uuid,uuid),api.client_migration_retry_row(uuid,uuid,integer,uuid),api.client_migration_list(uuid,jsonb),api.client_migration_detail(uuid,uuid)to service_role;

-- Batch activation uses explicit row aliases against the loop record.
create or replace function api.client_migration_activate_batch(p_actor_id uuid,p_batch_id uuid,p_expected_version integer,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare batch app_private.client_migration_batches%rowtype;row_item record;report jsonb;
begin
 select * into batch from app_private.client_migration_batches where client_migration_batch_id=p_batch_id for update;
 if batch.lifecycle_status='completed' then return batch.reconciliation_report||jsonb_build_object('duplicate',true);end if;
 if batch.version<>p_expected_version or batch.lifecycle_status not in('approved','completed_with_exceptions')then raise exception 'stale_or_invalid_batch' using errcode='40001';end if;
 perform app_private.client_migration_require(p_actor_id,'client_migration.activate',null,true);
 update app_private.client_migration_batches set lifecycle_status='activating',version=version+1,updated_at=now()where client_migration_batch_id=p_batch_id;
 insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('client-migration','ClientMigration.ActivationStarted',1,'migration-batch',p_batch_id,jsonb_build_object('batchId',p_batch_id),p_correlation_id,'user',p_actor_id::text,now());
 for row_item in select source_row.client_migration_row_id from app_private.client_migration_source_rows source_row where source_row.client_migration_batch_id=p_batch_id loop begin perform api.client_migration_activate_row(p_actor_id,row_item.client_migration_row_id,p_correlation_id);exception when others then insert into app_private.client_migration_row_outcomes(client_migration_row_id,outcome,technical_failure_code,result)values(row_item.client_migration_row_id,'failed',sqlstate,jsonb_build_object('rowId',row_item.client_migration_row_id))on conflict(client_migration_row_id)do update set outcome='failed',attempt_count=app_private.client_migration_row_outcomes.attempt_count+1,technical_failure_code=sqlstate,last_attempt_at=now();end;end loop;
 select jsonb_build_object('batchId',p_batch_id,'totalSourceRows',batch.row_count,'processed',count(*),'activated',count(*)filter(where outcome.outcome='activated'),'skipped',count(*)filter(where outcome.outcome='skipped'),'failed',count(*)filter(where outcome.outcome='failed'),'conflicts',count(*)filter(where outcome.outcome='conflict'),'referenceCoverage',count(*)filter(where exists(select 1 from app_private.client_migration_entity_provenance provenance where provenance.client_migration_row_id=source_row.client_migration_row_id)),'dataQualityWarnings',batch.profile) into report from app_private.client_migration_source_rows source_row left join app_private.client_migration_row_outcomes outcome using(client_migration_row_id)where source_row.client_migration_batch_id=p_batch_id;
 update app_private.client_migration_batches set lifecycle_status=case when (report->>'failed')::int>0 then'completed_with_exceptions'else'completed'end,reconciliation_report=report,completed_at=now(),version=version+1,updated_at=now()where client_migration_batch_id=p_batch_id;
 insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('client-migration','ClientMigration.BatchCompleted',1,'migration-batch',p_batch_id,jsonb_build_object('batchId',p_batch_id,'activated',report->'activated','failed',report->'failed'),p_correlation_id,'user',p_actor_id::text,now());return report;
end$$;
revoke all on function api.client_migration_activate_batch(uuid,uuid,integer,uuid) from public,anon,authenticated;
grant execute on function api.client_migration_activate_batch(uuid,uuid,integer,uuid) to service_role;

create or replace function api.client_migration_bulk_review_safe(p_actor_id uuid,p_batch_id uuid,p_mode text,p_reason text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare affected integer;
begin
 perform app_private.client_migration_require(p_actor_id,'client_migration.review',null,true);
 if p_mode not in('approve_new_without_warnings','approve_no_change') then raise exception 'unsafe_bulk_mode' using errcode='22023';end if;
 insert into app_private.client_migration_row_decisions(client_migration_row_id,actor_id,decision,approved_plan,reason)
 select source_row.client_migration_row_id,p_actor_id,case when p_mode='approve_no_change' then'no_change'else'approved'end,version_row.proposed_plan,p_reason
 from app_private.client_migration_source_rows source_row join app_private.client_migration_row_versions version_row using(client_migration_row_id)
 where source_row.client_migration_batch_id=p_batch_id and jsonb_array_length(version_row.validation_errors)=0 and ((p_mode='approve_no_change' and version_row.classification='ready_existing_service_no_change')or(p_mode='approve_new_without_warnings' and version_row.classification='ready_create_new_client_address_service')) on conflict(client_migration_row_id)do nothing;
 get diagnostics affected=row_count;
 insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('client_migration.safe_bulk_review',p_actor_id,'client-migration','migration-batch',p_batch_id,p_correlation_id,jsonb_build_object('mode',p_mode,'affectedRows',affected));
 return jsonb_build_object('batchId',p_batch_id,'mode',p_mode,'affectedRows',affected);
end$$;
revoke all on function api.client_migration_bulk_review_safe(uuid,uuid,text,text,uuid) from public,anon,authenticated;
grant execute on function api.client_migration_bulk_review_safe(uuid,uuid,text,text,uuid) to service_role;

create or replace function api.client_migration_rows(p_actor_id uuid,p_batch_id uuid,p_query jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare detail jsonb;
begin detail:=api.client_migration_detail(p_actor_id,p_batch_id);return jsonb_build_object('items',(select coalesce(jsonb_agg(item),'[]')from jsonb_array_elements(detail->'rows')item where nullif(p_query->>'classification','')is null or item->>'classification'=p_query->>'classification'),'batchId',p_batch_id);end$$;
create or replace function api.client_migration_row_detail(p_actor_id uuid,p_row_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare batch_id uuid;detail jsonb;result jsonb;begin select client_migration_batch_id into batch_id from app_private.client_migration_source_rows where client_migration_row_id=p_row_id;if batch_id is null then raise exception 'not found'using errcode='P0002';end if;detail:=api.client_migration_detail(p_actor_id,batch_id);select item into result from jsonb_array_elements(detail->'rows')item where item->>'rowId'=p_row_id::text;return result;end$$;
create or replace function api.client_migration_report(p_actor_id uuid,p_batch_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare b app_private.client_migration_batches%rowtype;begin select * into b from app_private.client_migration_batches where client_migration_batch_id=p_batch_id;perform app_private.client_migration_require(p_actor_id,'client_migration.read',null,true);if b.client_migration_batch_id is null then raise exception 'not found'using errcode='P0002';end if;return coalesce(b.reconciliation_report,jsonb_build_object('batchId',p_batch_id,'status',b.lifecycle_status,'available',false));end$$;
revoke all on function api.client_migration_rows(uuid,uuid,jsonb),api.client_migration_row_detail(uuid,uuid),api.client_migration_report(uuid,uuid)from public,anon,authenticated;
grant execute on function api.client_migration_rows(uuid,uuid,jsonb),api.client_migration_row_detail(uuid,uuid),api.client_migration_report(uuid,uuid)to service_role;
